<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, reactive, ref, watch } from 'vue';
import { ElMessage, ElMessageBox, type FormInstance, type FormRules } from 'element-plus';
import { ChevronDown, Download, Plus, Search } from 'lucide-vue-next';
import QueryPanel from '../components/QueryPanel.vue';
import QueryField from '../components/QueryField.vue';
import OperationsMap from '../components/OperationsMap.vue';
import { api } from '../api';
import { useSessionStore } from '../stores/session';
import { useResponsiveDrawer } from '../province-monitoring';
import { useSubjectList, subjectError } from '../subject-management';
import { regionTypes, admissionDate, admissionTime, useAdmissionOptions, can, exportAdmission } from '../admission';
import '../admission.css';
const session=useSessionStore(),width=useResponsiveDrawer(800),canWrite=computed(()=>can(session.user,'operation:region:write'));
const {filters,rows,total,page,loading,error,load,search,reset,getFilters}=useSubjectList('/operations/regions',{enterpriseId:'',regionType:''},false);
const {options,loading:optionsLoading,error:optionsError,load:loadOptions}=useAdmissionOptions('/operations/regions/options');
const drawer=ref(false),detail=ref<any>(null),detailId=ref(''),detailLoading=ref(false),detailError=ref(''),tab=ref('range'),editor=ref(false),editingId=ref(''),saving=ref(false),exporting=ref(false),selected=ref<any[]>([]),formRef=ref<FormInstance>(),mapRef=ref<InstanceType<typeof OperationsMap>>(),showCoordinates=ref(false),isDrawing=ref(false);let generation=0;
const defaults=()=>({businessNo:'',name:'',enterpriseId:'',organizationId:session.user?.organizationId??'',regionType:'OPERATION',approvalResultId:'',approvalStatus:'APPROVED',validFrom:admissionDate(new Date().toISOString()),validTo:'',speedLimit:20,allowedHours:'06:00-22:00',ruleDescription:'',vehicleIds:[] as string[],polygonText:''});
const form=reactive(defaults()),rules:FormRules={businessNo:[{required:true,message:'请填写区域编号',trigger:'blur'}],name:[{required:true,message:'请填写区域名称',trigger:'blur'}],organizationId:[{required:true,message:'请选择管理机构',trigger:'change'}],validFrom:[{required:true,message:'请选择生效日期',trigger:'change'}]};
const vehicleOptions=computed(()=>options.value.vehicles?.filter((v:any)=>!form.enterpriseId||v.enterpriseId===form.enterpriseId)??[]);
const approvalOptions=computed(()=>options.value.approvalResults?.filter((r:any)=>!form.enterpriseId||r.application.enterpriseId===form.enterpriseId)??[]);
function polygon(){return form.polygonText.split(/\r?\n/).filter(line=>line.trim()).map(line=>{const pair=line.split(',').map(value=>Number(value.trim()));if(pair.length!==2||!pair.every(Number.isFinite))throw new Error('每行填写一组有效经度、纬度，以英文逗号分隔');return {longitude:pair[0],latitude:pair[1]}})}
const formRegions=computed(()=>{try{const points=polygon();if(points.length>=3)return [{...form,id:'editing',status:'ACTIVE',polygon:points,organization:{id:form.organizationId,name:''},enterprise:null,approvalResult:null,validTo:form.validTo||null,vehicles:[],_count:{records:0}}] as any;return rows.value.slice(0,1)}catch{return rows.value.slice(0,1)}});
async function loadDetail(){if(!drawer.value||!detailId.value)return;const request=++generation;detail.value=null;detailError.value='';detailLoading.value=true;try{const item=await api(`/operations/regions/${detailId.value}`);if(request===generation)detail.value=item}catch(e){if(request===generation)detailError.value=subjectError(e)}finally{if(request===generation)detailLoading.value=false}}
function open(row:any){detailId.value=row.id;tab.value='range';drawer.value=true;loadDetail()}
watch(drawer,value=>{if(!value)generation++});onBeforeUnmount(()=>generation++);
function edit(row?:any){drawer.value=false;editingId.value=row?.id??'';Object.assign(form,defaults());if(row)Object.assign(form,{businessNo:row.businessNo,name:row.name,enterpriseId:row.enterpriseId??'',organizationId:row.organizationId,regionType:row.regionType,approvalResultId:row.approvalResult?.id??'',approvalStatus:row.approvalStatus,validFrom:admissionDate(row.validFrom),validTo:row.validTo?admissionDate(row.validTo):'',speedLimit:row.speedLimit,allowedHours:row.allowedHours??'06:00-22:00',ruleDescription:row.ruleDescription??'',vehicleIds:row.vehicles.map((v:any)=>v.vehicleId??v.vehicle.id),polygonText:row.polygon.map((p:any)=>`${p.longitude},${p.latitude}`).join('\n')});else form.businessNo=`QY-${session.user?.workspace?.cityCode??'SD'}-${new Date().getFullYear()}-${Date.now().toString().slice(-6)}`;showCoordinates.value=false;isDrawing.value=false;editor.value=true}
function enterpriseChanged(){form.vehicleIds=[];form.approvalResultId='';const enterprise=options.value.enterprises.find((e:any)=>e.id===form.enterpriseId);if(enterprise)form.organizationId=enterprise.organizationId}
function drawn(points:Array<{longitude:number;latitude:number}>){isDrawing.value=false;if(points.length>1000)return ElMessage.warning('道路范围最多支持1000个边界顶点');form.polygonText=points.map(p=>`${p.longitude.toFixed(7)},${p.latitude.toFixed(7)}`).join('\n');mapRef.value?.cancelPolygonDraw();ElMessage.success('道路通行边界已绘制，可继续保存')}
async function draw(){if(isDrawing.value){mapRef.value?.cancelPolygonDraw();isDrawing.value=false;return}await nextTick();isDrawing.value=!!await mapRef.value?.beginPolygonDraw();if(!isDrawing.value)ElMessage.warning('地图绘制工具尚未就绪，可重试或展开坐标录入')}
async function save(){if(!await formRef.value?.validate().catch(()=>false))return;let points;try{points=polygon();if(points.length<3)throw new Error('请先在地图绘制至少3个顶点的区域边界')}catch(e){return ElMessage.warning(subjectError(e))}saving.value=true;try{const payload:any={...form,enterpriseId:form.enterpriseId||null,polygon:points,validTo:form.validTo||null,approvalResultId:form.approvalResultId||undefined};delete payload.polygonText;const item=await api<any>(editingId.value?`/operations/regions/${editingId.value}`:'/operations/regions',{method:editingId.value?'PATCH':'POST',body:JSON.stringify(payload)});editor.value=false;ElMessage.success(editingId.value?'区域已更新':'区域已新增');await load();open(item)}catch(e){ElMessage.error(subjectError(e))}finally{saving.value=false}}
async function toggle(row:any){try{await ElMessageBox.confirm(`确定${row.status==='ACTIVE'?'停用':'启用'}“${row.name}”？`,'区域状态调整',{confirmButtonText:'确认',cancelButtonText:'取消',type:'warning'});await api(`/operations/regions/${row.id}/status`,{method:'PATCH',body:JSON.stringify({status:row.status==='ACTIVE'?'INACTIVE':'ACTIVE'})});ElMessage.success('区域状态已更新');await load();if(drawer.value)await loadDetail()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(subjectError(e))}}
async function exportRows(){exporting.value=true;try{await exportAdmission('/operations/regions',getFilters(),[['区域编号',r=>r.businessNo],['区域名称',r=>r.name],['关联企业',r=>r.enterprise?.name||'公共区域'],['区域类型',r=>regionTypes[r.regionType]],['关联车辆',r=>r.vehicles.length],['允许时段',r=>r.allowedHours],['限速',r=>r.speedLimit],['生效日期',r=>admissionDate(r.validFrom)],['有效期至',r=>admissionDate(r.validTo)],['状态',r=>r.status==='ACTIVE'?'已启用':'已停用']],'通行区域',selected.value)}catch(e){ElMessage.error(subjectError(e))}finally{exporting.value=false}}
</script>
<template>
<section class="city-subject-page admission-page" aria-label="通行区域"><h1 class="sr-only">通行区域</h1>
  <QueryPanel class="subject-query admission-query" :loading="loading" @search="search" @reset="reset"><QueryField label="关键词" keyword><el-input v-model="filters.q" :prefix-icon="Search" clearable placeholder="搜索区域编号、名称或企业" aria-label="搜索通行区域"/></QueryField><QueryField label="企业"><el-select v-model="filters.enterpriseId" aria-label="区域企业" filterable clearable placeholder="全部企业" :loading="optionsLoading" :disabled="!!optionsError"><el-option v-for="item in options.enterprises" :key="item.id" :label="item.name" :value="item.id"/></el-select></QueryField><QueryField label="区域类型"><el-select v-model="filters.regionType" aria-label="区域类型" clearable placeholder="全部类型"><el-option v-for="(label,value) in regionTypes" :key="value" :label="label" :value="value"/></el-select></QueryField><QueryField label="启用状态"><el-select v-model="filters.status" aria-label="区域启用状态" clearable placeholder="全部状态"><el-option label="已启用" value="ACTIVE"/><el-option label="已停用" value="INACTIVE"/></el-select></QueryField></QueryPanel>
  <section class="subject-list" aria-label="通行区域列表"><header class="subject-list-header"><h2>通行区域 <span v-if="!error" class="subject-count">{{total}}</span></h2><div class="subject-tools"><el-button :icon="Download" :loading="exporting" :disabled="loading||!!error" @click="exportRows">{{selected.length?'导出选中':'导出'}}</el-button><el-button v-if="canWrite" type="primary" :icon="Plus" :disabled="optionsLoading||!!optionsError" @click="edit()">新增区域</el-button></div></header>
    <div v-if="optionsError" class="subject-inline-error" role="alert">区域维护选项加载失败：{{optionsError}}<el-button text @click="loadOptions">重试</el-button></div><div v-if="error" class="subject-error" role="alert"><strong>区域列表加载失败</strong><span>{{error}}</span><el-button @click="load">重试</el-button></div>
    <div v-else class="subject-table-host"><el-table v-loading="loading" :data="rows" row-key="id" height="100%" class="subject-table" empty-text="暂无符合条件的通行区域" @selection-change="selected=$event"><el-table-column type="selection" width="42"/><el-table-column label="区域名称 / 编号" min-width="230"><template #default="{row}"><button class="subject-identity" @click="open(row)"><strong>{{row.name}}</strong><span>{{row.businessNo}}</span></button></template></el-table-column><el-table-column label="关联企业" min-width="235" show-overflow-tooltip><template #default="{row}">{{row.enterprise?.name||'公共区域'}}</template></el-table-column><el-table-column label="区域类型" min-width="115"><template #default="{row}">{{regionTypes[row.regionType]||row.regionType}}</template></el-table-column><el-table-column label="关联车辆" min-width="105"><template #default="{row}"><span class="subject-number">{{row.vehicles.length}}</span><span class="subject-unit">辆</span></template></el-table-column><el-table-column label="运行条件" min-width="220"><template #default="{row}"><div class="subject-identity"><strong>{{row.allowedHours||'未限制时段'}} · {{row.speedLimit}} km/h</strong><span>{{admissionDate(row.validFrom)}} 至 {{row.validTo?admissionDate(row.validTo):'长期'}}</span></div></template></el-table-column><el-table-column label="状态" min-width="110"><template #default="{row}"><el-tag :type="row.status==='ACTIVE'?'success':'info'">{{row.status==='ACTIVE'?'已启用':'已停用'}}</el-tag></template></el-table-column><el-table-column label="操作" :width="canWrite?225:100" fixed="right"><template #default="{row}"><div class="subject-row-actions"><el-button link type="primary" :aria-label="`${row.name}查看范围`" @click="open(row)">查看范围</el-button><el-button v-if="canWrite" link type="primary" :aria-label="`编辑${row.name}`" @click="edit(row)">编辑</el-button><el-dropdown v-if="canWrite" trigger="click"><el-button link type="primary" :aria-label="`${row.name}更多操作`">更多<ChevronDown :size="12"/></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item @click="toggle(row)">{{row.status==='ACTIVE'?'停用区域':'启用区域'}}</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></template></el-table-column></el-table></div><footer v-if="!error" class="subject-footer"><span>当前显示 {{rows.length}} 条</span><el-pagination v-model:current-page="page" :total="total" :page-size="20" :pager-count="5" layout="total,prev,pager,next" background small/></footer>
  </section>
  <el-drawer v-model="drawer" title="通行区域详情" :size="width" class="subject-drawer" destroy-on-close><div v-if="detailError" class="subject-error" role="alert"><strong>区域详情加载失败</strong><span>{{detailError}}</span><el-button @click="loadDetail">重试</el-button></div><el-skeleton v-else-if="detailLoading" :rows="9" animated/><template v-else-if="detail"><div class="subject-detail-title"><div><h2>{{detail.name}}</h2><p>{{detail.businessNo}}</p></div><el-tag :type="detail.status==='ACTIVE'?'success':'info'">{{detail.status==='ACTIVE'?'已启用':'已停用'}}</el-tag></div><el-tabs v-model="tab"><el-tab-pane label="范围与规则" name="range"/><el-tab-pane :label="`关联车辆（${detail.vehicles.length}）`" name="vehicles"/><el-tab-pane label="调整记录" name="history"/></el-tabs><template v-if="tab==='range'"><div class="admission-map"><OperationsMap :key="detail.id" mode="regions" :regions="[detail]" :selected-id="detail.id" height="100%"/></div><dl class="subject-detail-grid"><div class="wide"><dt>关联企业</dt><dd>{{detail.enterprise?.name||'公共区域'}}</dd></div><div><dt>关联车辆</dt><dd>{{detail.vehicles.length}} 辆</dd></div><div><dt>允许时段</dt><dd>{{detail.allowedHours||'未限制时段'}}</dd></div><div><dt>区域限速</dt><dd>{{detail.speedLimit}} km/h</dd></div><div><dt>审批依据</dt><dd>{{detail.approvalResult?.documentNo||'未关联审批文书'}}</dd></div><div class="wide"><dt>有效期</dt><dd>{{admissionDate(detail.validFrom)}} 至 {{detail.validTo?admissionDate(detail.validTo):'长期'}}</dd></div><div class="wide"><dt>区域规则</dt><dd>{{detail.ruleDescription||'—'}}</dd></div></dl></template><el-table v-else-if="tab==='vehicles'" :data="detail.vehicles" empty-text="尚未关联车辆"><el-table-column label="车辆名称" min-width="180"><template #default="{row}">{{row.vehicle.name}}</template></el-table-column><el-table-column label="车辆编号" min-width="200"><template #default="{row}">{{row.vehicle.unifiedCode||row.vehicle.businessNo}}</template></el-table-column></el-table><template v-else><el-timeline v-if="detail.history.length" class="admission-timeline"><el-timeline-item v-for="(item,index) in [...detail.history].reverse()" :key="index" :timestamp="admissionTime(item.at)" placement="top"><strong>{{item.summary}} · {{item.actor}}</strong><p v-if="item.before">调整前：{{item.before.allowedHours||'未限制时段'}} · {{item.before.speedLimit}}km/h · {{admissionDate(item.before.validTo)}}</p></el-timeline-item></el-timeline><el-empty v-else description="暂无调整记录" :image-size="64"/></template></template><template #footer><el-button @click="drawer=false">关闭</el-button><el-button v-if="canWrite&&detail" type="primary" @click="edit(detail)">编辑区域</el-button></template></el-drawer>
  <el-drawer v-model="editor" :title="editingId?'编辑通行区域':'新增通行区域'" :size="width" class="subject-drawer" destroy-on-close :close-on-click-modal="!saving" :show-close="!saving"><el-form ref="formRef" :model="form" :rules="rules" label-position="top" class="subject-form" :disabled="saving"><el-form-item label="区域编号" prop="businessNo"><el-input v-model="form.businessNo" maxlength="60"/></el-form-item><el-form-item label="区域名称" prop="name"><el-input v-model="form.name" maxlength="100"/></el-form-item><el-form-item label="关联企业" prop="enterpriseId"><el-select v-model="form.enterpriseId" aria-label="区域关联企业" filterable clearable placeholder="公共区域（不限企业）" @change="enterpriseChanged"><el-option v-for="item in options.enterprises" :key="item.id" :label="item.name" :value="item.id"/></el-select></el-form-item><el-form-item label="管理机构" prop="organizationId"><el-select v-model="form.organizationId" aria-label="区域管理机构" filterable><el-option v-for="item in options.organizations" :key="item.id" :label="item.name" :value="item.id"/></el-select></el-form-item><el-form-item label="区域类型"><el-select v-model="form.regionType" aria-label="维护区域类型"><el-option v-for="(label,value) in regionTypes" :key="value" :label="label" :value="value"/></el-select></el-form-item><el-form-item label="批准状态"><el-select v-model="form.approvalStatus" aria-label="区域批准状态"><el-option label="已批准" value="APPROVED"/><el-option label="待批准" value="PENDING"/><el-option label="未批准" value="REJECTED"/></el-select></el-form-item><el-form-item label="关联审批依据" class="wide"><el-select v-model="form.approvalResultId" aria-label="区域审批依据" filterable clearable placeholder="选择已通过的审批结果"><el-option v-for="item in approvalOptions" :key="item.id" :label="`${item.documentNo} · ${item.application.title}`" :value="item.id"/></el-select></el-form-item><el-form-item label="生效日期" prop="validFrom"><el-date-picker v-model="form.validFrom" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="有效期至"><el-date-picker v-model="form.validTo" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="允许时段"><el-input v-model="form.allowedHours" placeholder="06:00-22:00"/></el-form-item><el-form-item label="区域限速（km/h）"><el-input-number v-model="form.speedLimit" :min="1" :max="80"/></el-form-item><el-form-item label="关联车辆" class="wide"><el-select v-model="form.vehicleIds" aria-label="区域关联车辆" multiple filterable collapse-tags collapse-tags-tooltip><el-option v-for="vehicle in vehicleOptions" :key="vehicle.id" :value="vehicle.id" :label="vehicle.name"/></el-select></el-form-item><div class="wide"><div class="admission-map-tools"><span>{{isDrawing?'正在绘制：单击添加顶点，双击结束。':'沿实际道路边界绘制窄通行范围，避免圈入整块街区、建筑或水域。'}}</span><el-button :disabled="saving" @click="draw">{{isDrawing?'取消绘制':'重新绘制'}}</el-button></div><div class="admission-map"><OperationsMap ref="mapRef" mode="regions" :regions="formRegions" height="100%" @polygon-drawn="drawn"/></div><el-button text type="primary" @click="showCoordinates=!showCoordinates">{{showCoordinates?'收起坐标':'展开坐标录入'}}</el-button><el-input v-if="showCoordinates" v-model="form.polygonText" aria-label="区域边界坐标" type="textarea" :rows="5" placeholder="每行一组经度,纬度"/></div><el-form-item label="区域规则" class="wide"><el-input v-model="form.ruleDescription" type="textarea" :rows="3"/></el-form-item></el-form><template #footer><el-button :disabled="saving" @click="editor=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存区域</el-button></template></el-drawer>
</section>
</template>
